static IntervalsSource analyzeText(CachingTokenFilter stream, int maxGaps, boolean ordered)
    throws IOException {
  assert stream != null;

  TermToBytesRefAttribute termAtt = stream.getAttribute(TermToBytesRefAttribute.class);
  PositionIncrementAttribute posIncAtt = stream.addAttribute(PositionIncrementAttribute.class);
  PositionLengthAttribute posLenAtt = stream.addAttribute(PositionLengthAttribute.class);

  if (termAtt == null) {
    return NO_INTERVALS;
  }

  int numTokens = 0;
  boolean hasSynonyms = false;
  boolean isGraph = false;

  stream.reset();
  while (stream.incrementToken()) {
    numTokens++;
    int positionIncrement = posIncAtt.getPositionIncrement();
    int positionLength = posLenAtt.getPositionLength();
    hasSynonyms = detectSynonymSignal(hasSynonyms, positionIncrement);
    isGraph = detectGraphSignal(isGraph, positionLength);
    COORDINATOR.observeToken(positionIncrement, positionLength, termAtt.getBytesRef().length);
  }
  COORDINATOR.observeAnalysis(numTokens, hasSynonyms, isGraph, maxGaps, ordered);

  if (numTokens == 0) {
    return NO_INTERVALS;
  } else if (numTokens == 1) {
    return analyzeTerm(stream);
  } else if (isGraph) {
    return combineSources(analyzeGraph(stream), maxGaps, ordered);
  } else {
    if (hasSynonyms) {
      return analyzeSynonyms(stream, maxGaps, ordered);
    } else {
      return combineSources(analyzeTerms(stream), maxGaps, ordered);
    }
  }
}

static boolean detectSynonymSignal(boolean current, int positionIncrement) {
  if (positionIncrement == 0) {
    return true;
  }
  return current;
}

static boolean detectGraphSignal(boolean current, int positionLength) {
  if (positionLength > 1) {
    return true;
  }
  return current;
}

private static IntervalsSource analyzeTerm(TokenStream ts) throws IOException {
  TermToBytesRefAttribute bytesAtt = ts.addAttribute(TermToBytesRefAttribute.class);
  ts.reset();
  ts.incrementToken();
  return termSource(BytesRef.deepCopyOf(bytesAtt.getBytesRef()));
}

private static IntervalsSource combineSources(
    List<IntervalsSource> sources, int maxGaps, boolean ordered) {
  if (sources.size() == 0) {
    return NO_INTERVALS;
  }
  if (sources.size() == 1) {
    return sources.get(0);
  }
  IntervalsSource[] sourcesArray = sources.toArray(new IntervalsSource[0]);
  COORDINATOR.plannedPhraseWidth(sourcesArray.length, maxGaps);
  if (maxGaps == 0 && ordered) {
    return phraseSources(sourcesArray);
  }
  IntervalsSource inner =
      ordered ? orderedSources(sourcesArray) : unorderedSources(sourcesArray);
  if (maxGaps == -1) {
    return inner;
  }
  return maxGapsSource(maxGaps, inner);
}

private static List<IntervalsSource> analyzeTerms(TokenStream ts) throws IOException {
  List<IntervalsSource> terms = new ArrayList<>();
  TermToBytesRefAttribute bytesAtt = ts.addAttribute(TermToBytesRefAttribute.class);
  PositionIncrementAttribute posAtt = ts.addAttribute(PositionIncrementAttribute.class);
  ts.reset();
  while (ts.incrementToken()) {
    BytesRef term = bytesAtt.getBytesRef();
    int precedingSpaces = posAtt.getPositionIncrement() - 1;
    terms.add(extend(termSource(BytesRef.deepCopyOf(term)), precedingSpaces));
  }
  ts.end();
  return terms;
}

private static IntervalsSource extend(IntervalsSource source, int precedingSpaces) {
  if (precedingSpaces == 0) {
    return source;
  }
  return extendSource(source, precedingSpaces, 0);
}

private static IntervalsSource analyzeSynonyms(TokenStream ts, int maxGaps, boolean ordered)
    throws IOException {
  List<IntervalsSource> terms = new ArrayList<>();
  List<IntervalsSource> synonyms = new ArrayList<>();
  TermToBytesRefAttribute bytesAtt = ts.addAttribute(TermToBytesRefAttribute.class);
  PositionIncrementAttribute posAtt = ts.addAttribute(PositionIncrementAttribute.class);
  ts.reset();
  int spaces = 0;
  while (ts.incrementToken()) {
    int posInc = posAtt.getPositionIncrement();
    if (posInc > 0) {
      if (synonyms.size() == 1) {
        terms.add(extend(synonyms.get(0), spaces));
      } else if (synonyms.size() > 1) {
        terms.add(extend(orSources(true, synonyms), spaces));
      }
      synonyms.clear();
      spaces = posInc - 1;
    }
    synonyms.add(termSource(BytesRef.deepCopyOf(bytesAtt.getBytesRef())));
  }
  if (synonyms.size() == 1) {
    terms.add(extend(synonyms.get(0), spaces));
  } else {
    terms.add(extend(orSources(true, synonyms), spaces));
  }
  return combineSources(terms, maxGaps, ordered);
}

private static List<IntervalsSource> analyzeGraph(TokenStream source) throws IOException {
  source.reset();
  GraphTokenStreamFiniteStrings graph = new GraphTokenStreamFiniteStrings(source);

  List<IntervalsSource> clauses = new ArrayList<>();
  int[] articulationPoints = graph.articulationPoints();
  int lastState = 0;
  int maxClauseCount = BooleanQuery.getMaxClauseCount();
  for (int i = 0; i <= articulationPoints.length; i++) {
    int start = lastState;
    int end = -1;
    if (i < articulationPoints.length) {
      end = articulationPoints[i];
    }
    lastState = end;
    if (graph.hasSidePath(start)) {
      List<IntervalsSource> paths = new ArrayList<>();
      Iterator<TokenStream> it = graph.getFiniteStrings(start, end);
      while (it.hasNext()) {
        TokenStream ts = it.next();
        IntervalsSource phrase = combineSources(analyzeTerms(ts), 0, true);
        if (paths.size() >= maxClauseCount) {
          throw new BooleanQuery.TooManyClauses();
        }
        paths.add(phrase);
      }
      if (paths.size() > 0) {
        clauses.add(orSources(true, paths));
      }
    } else {
      Iterator<TokenStream> it = graph.getFiniteStrings(start, end);
      TokenStream ts = it.next();
      clauses.addAll(analyzeTerms(ts));
      assert it.hasNext() == false;
    }
  }
  return clauses;
}

